#include <iostream>
typedef int Int;
void f(int i) {
    std::cout << "Function f with int called, value: " << i << std::endl;
}
void f(Int i) {
    std::cout << "Function f with Int (typedef) called, value: " << i << std::endl;
}
int main() {
    f(42); // Calls f(int), as Int is a typedef for int
    return 0;
}
